struct P { public int X; }
class C { public int X; }

var a = new P { X = 1 };
var b = a;        // struct: b is a copy
b.X = 99;

var c = new C { X = 1 };
var d = c;        // class: d is the same object
d.X = 99;

System.Console.WriteLine($"struct a.X={a.X} (unchanged), class c.X={c.X} (changed)");

string Describe(int? n) => n switch
{
    null         => "nothing",
    < 0          => "negative",
    0            => "zero",
    > 0 and < 10 => "small",
    _            => "big"
};

foreach (int? x in new int?[] { null, -3, 0, 7, 42 })
    System.Console.WriteLine($"{x}: {Describe(x)}");

bool TryHalve(int n, out int result)
{
    result = n / 2;
    return n % 2 == 0;
}

(int min, int max) Range(int[] a) => (a.Min(), a.Max());

var ok = TryHalve(10, out int h);
var (lo, hi) = Range(new[] { 5, 2, 9, 1 });
System.Console.WriteLine($"halve ok={ok} h={h}; range {lo}..{hi}");

interface IShape { double Area(); }

abstract class Shape : IShape
{
    public string Name = "";
    public abstract double Area();
}

class Circle : Shape
{
    public double R;
    public Circle(double r) { R = r; Name = "circle"; }
    public override double Area() => 3.14159 * R * R;
}

class Square : Shape
{
    public double S;
    public Square(double s) { S = s; Name = "square"; }
    public override double Area() => S * S;
}

Shape[] shapes = { new Circle(2), new Square(3) };
foreach (var s in shapes)
    System.Console.WriteLine($"{s.Name}: {s.Area():F2}");

